photo=''.join(f'<img class="specimen-image" data-id="{m["id"]}" data-active="{str(i==0).lower()}" aria-hidden="{str(i!=0).lower()}" src="assets/{m["id"]}.webp" alt="{m["name"]}：{m["short"]}的生成物件示意" width="1254" height="1254">' for i,m in enumerate(methods))
buttons=''.join(f'<button type="button" class="method-button" data-method="{m["id"]}" aria-pressed="{str(i==0).lower()}"><span class="number">{m["no"]}</span><span class="name">{m["name"]}</span><span class="english">{m["en"]}</span><span class="mark" aria-hidden="true">↗</span></button>' for i,m in enumerate(methods))
compare=''.join(f'<figure><div class="diagram-shell">{diagram(m["id"],"compare-"+m["id"])}<figcaption><h3>{m["name"]}</h3><span class="en">{m["en"]}</span></figcaption></div><p class="route-summary">{m["short"]}</p></figure>' for m in methods)
rows=''
for label,color,values in [('果皮与果肉','fruit',['保留','已去除¹','已去除¹']),('黏液层','gel',['保留','去除','保留不等']),('羊皮层','parchment',['保留','保留','保留']),('种子','seed',['保留','保留','保留'])]:
    rows+='<div class="matrix-row" role="row"><span class="matrix-label" role="rowheader"><i class="layer-dot" style="--swatch:var(--'+color+')"></i>'+label+'</span>'+''.join('<span role="cell" class="matrix-value '+('removed' if ('去除' in v) else 'partial' if '不等' in v else '')+'">'+('<strong>'+v+'</strong>' if v=='保留' else v)+'</span>' for v in values)+'</div>'
templates=''.join('<template data-diagram="'+m['id']+'">'+diagram(m['id'],'detail-'+m['id'])+'</template>' for m in methods)
html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>留下什么 · 三种处理路线</title><style>'''+style+'''</style></head><body class="lab-page"><main class="lab" data-process-lab data-method="natural" data-compare="false">
<button type="button" class="compare-close" data-compare-close>返回单独观察 ↙</button>
<section class="compare-stage" aria-label="三种路线的组织结构比较"><header class="compare-intro"><h2>相同的起点，留下不同的层。</h2><p>比较时点：开始干燥时</p></header><div class="compare">'''+compare+'''</div><div class="layer-matrix" role="table" aria-label="组织去留对照"><div class="matrix-row matrix-head" role="row"><span role="columnheader">组织</span><span role="columnheader">日晒</span><span role="columnheader">水洗</span><span role="columnheader">蜜处理</span></div>'''+rows+'''</div><div class="comparison-note"><span><i class="key-dashed"></i>虚线：已去除组织的位置</span><span>¹ 去皮及去除大部分果肉。图像为材料示意，非实测剖面；厚度不作测量，银皮省略。</span></div></section>
<div class="specimen-layout"><figure class="specimen-view"><div class="specimen-stack">'''+photo+'''<span class="specimen-note">开始干燥时</span></div><figcaption class="view-caption" data-short>整果进入干燥</figcaption></figure><div class="method-column"><p class="method-context">选择一种处理路线 / AT THE SAME MOMENT</p><div class="methods" role="group" aria-label="选择处理路线">'''+buttons+'''</div><div class="method-response"><h3 data-method-title></h3><p data-method-copy></p></div><div class="method-actions"><button type="button" data-detail aria-expanded="false" aria-controls="layer-panel">看留下的层 ＋</button><button type="button" data-compare-button>三条路线并排看 ↗</button></div></div></div>
<section class="detail-panel" id="layer-panel" data-detail-panel data-open="false" aria-label="组织与步骤"><figure><div class="diagram-shell"><p class="diagram-title" data-diagram-title></p><div data-layer-image></div></div><figcaption class="diagram-caption"><i class="key-dashed"></i>已去除外层的原位置。材料图像与矢量标识叠合；厚度仅为说明，银皮省略。</figcaption></figure><div><ul class="layer-list" data-layers></ul><ol class="route-steps" data-steps></ol><p class="route-note" data-note></p></div></section>'''+templates+'''<p class="sr-only" data-process-live aria-live="polite"></p><footer class="lab-foot"><span class="principle">三条替代路线，比较时点相同；它们不构成先后顺序。</span><span>图像：AI 生成材料示意 · 组织关系：同尺度矢量标识</span></footer></main><script>'''
script='''(()=>{'use strict';
const data=METHODS,root=document.querySelector('[data-process-lab]');let selected='natural',heightFrame=0;
function report(){if(heightFrame)return;heightFrame=requestAnimationFrame(()=>{heightFrame=0;if(parent!==window)parent.postMessage({type:'coffee:height',height:Math.ceil(document.body.scrollHeight)},'*')})}
const observer=new ResizeObserver(report);observer.observe(document.body);addEventListener('load',report);document.fonts.ready.then(report);
const buttons=[...root.querySelectorAll('.method-button')],images=[...root.querySelectorAll('.specimen-image')],title=root.querySelector('[data-method-title]'),copy=root.querySelector('[data-method-copy]'),short=root.querySelector('[data-short]'),diagram=root.querySelector('[data-layer-image]'),layers=root.querySelector('[data-layers]'),steps=root.querySelector('[data-steps]'),note=root.querySelector('[data-note]'),detail=root.querySelector('[data-detail-panel]'),detailButton=root.querySelector('[data-detail]'),compareButton=root.querySelector('[data-compare-button]');
function select(id){const m=data.find(m=>m.id===id);if(!m)return;selected=id;root.dataset.method=id;for(const b of buttons)b.setAttribute('aria-pressed',String(b.dataset.method===id));for(const im of images){im.dataset.active=String(im.dataset.id===id);im.setAttribute('aria-hidden',String(im.dataset.id!==id))}title.textContent=m.title;copy.textContent=m.copy;short.textContent=m.short;diagram.replaceChildren(root.querySelector('[data-diagram="'+id+'"]').content.cloneNode(true));root.querySelector('[data-diagram-title]').textContent=m.name+' / 组织剖面';layers.replaceChildren(...m.layers.map((state,i)=>{const li=document.createElement('li'),dot=document.createElement('i'),name=document.createElement('span'),value=document.createElement('span');dot.className='layer-dot';dot.style.setProperty('--swatch','var(--'+['fruit','gel','parchment','seed'][i]+')');name.textContent=['果皮与果肉','黏液层','羊皮层','种子'][i];value.textContent=state;value.className='layer-state';li.dataset.removed=String(state.includes('去'));li.append(dot,name,value);return li}));steps.replaceChildren(...m.steps.map(t=>{const li=document.createElement('li');li.textContent=t;return li}));note.textContent=m.note;root.querySelector('[data-process-live]').textContent=m.name+'：'+m.short;report()}
buttons.forEach((b,i)=>{b.addEventListener('click',()=>select(b.dataset.method));b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight'||e.key==='ArrowDown')n=(i+1)%buttons.length;else if(e.key==='ArrowLeft'||e.key==='ArrowUp')n=(i+buttons.length-1)%buttons.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=buttons.length-1;else return;e.preventDefault();buttons[n].focus();select(buttons[n].dataset.method)})});
detailButton.addEventListener('click',()=>{const open=detail.dataset.open!=='true';detail.dataset.open=String(open);detailButton.setAttribute('aria-expanded',String(open));detailButton.textContent=open?'收起组织与步骤 −':'看留下的层 ＋';report()});
function revealStart(){window.scrollTo({top:0,behavior:'instant'});if(parent!==window)parent.postMessage({type:'coffee:reveal'},'*')}
compareButton.addEventListener('click',()=>{root.dataset.compare='true';root.querySelector('[data-compare-close]').focus({preventScroll:true});report();revealStart()});root.querySelector('[data-compare-close]').addEventListener('click',()=>{root.dataset.compare='false';compareButton.focus({preventScroll:true});report();revealStart()});
addEventListener('pagehide',()=>{observer.disconnect();cancelAnimationFrame(heightFrame);heightFrame=0},{once:true});select(selected);
})();'''.replace('METHODS',json.dumps(methods,ensure_ascii=False))
html+=script+'</script></body></html>'
(ROOT/'u03.html').write_text(html,encoding='utf-8')
(ROOT/'u03.css').write_text(style,encoding='utf-8')
(ROOT/'u03.js').write_text(script,encoding='utf-8')
(ROOT/'content.json').write_text(json.dumps({'methods':methods},ensure_ascii=False,indent=2),encoding='utf-8')
print('Built U03 hybrid material edition',len(html.encode()),'bytes; same interactive script, three registered material images')
